begin;
alter table public.patients add column if not exists status public.record_status not null default 'active';
create or replace function public.set_patient_status(target_patient uuid,new_status public.record_status,change_reason text) returns void language plpgsql security definer set search_path='' as $$declare fac uuid;org uuid;begin select p.organization_id,f.id into org,fac from public.patients p join public.facilities f on f.organization_id=p.organization_id where p.id=target_patient and public.has_privilege('patients.update',f.id) limit 1;if fac is null then raise exception 'Not authorized';end if;if new_status not in('active','inactive') or nullif(trim(change_reason),'') is null then raise exception 'Active/inactive status and reason are required';end if;update public.patients set status=new_status,updated_at=now(),version=version+1 where id=target_patient;insert into public.audit_events(organization_id,facility_id,actor_id,event_type,object_type,object_id,reason,details) values(org,fac,auth.uid(),case when new_status='inactive' then 'patient.archived' else 'patient.restored' end,'patient',target_patient,trim(change_reason),jsonb_build_object('status',new_status));end$$;
create or replace function public.cancel_encounter(target_encounter uuid,cancel_reason text) returns void language plpgsql security definer set search_path='' as $$declare fac uuid;org uuid;begin select e.facility_id,p.organization_id into fac,org from public.encounters e join public.patients p on p.id=e.patient_id where e.id=target_encounter;if fac is null or not public.has_privilege('clinical.write',fac) or nullif(trim(cancel_reason),'') is null then raise exception 'Authorization and cancellation reason are required';end if;if exists(select 1 from public.admissions a where a.encounter_id=target_encounter and a.status not in('cancelled','planned')) then raise exception 'Discharge admitted patients through ADT';end if;update public.encounters set status='cancelled' where id=target_encounter and status not in('completed','cancelled');if not found then raise exception 'Encounter cannot be cancelled';end if;insert into public.audit_events(organization_id,facility_id,actor_id,event_type,object_type,object_id,reason) values(org,fac,auth.uid(),'encounter.cancelled','encounter',target_encounter,trim(cancel_reason));end$$;
grant execute on function public.set_patient_status(uuid,public.record_status,text) to authenticated;grant execute on function public.cancel_encounter(uuid,text) to authenticated;
commit;
